import { NextResponse, type NextRequest } from "next/server";
import redirects from "../data/catalog/redirects.json";
import { defaultLocale, isLocale, LOCALE_COOKIE } from "./lib/i18n/config";

/**
 * 1. Legacy URLs from the previous website → new URLs (301), generated by the catalog import.
 * 2. Paths without a locale prefix → /{locale}/… using the visitor's saved choice, else English.
 */
const legacy = new Map<string, string>(
  (redirects as { from: string; to: string }[]).map((r) => [normalize(r.from), r.to]),
);

function normalize(pathname: string) {
  let p = pathname;
  try {
    p = decodeURIComponent(pathname);
  } catch {
    // keep the raw path if it is not valid percent-encoding
  }
  return p.length > 1 ? p.replace(/\/+$/, "") : p;
}

export function proxy(request: NextRequest) {
  const { pathname, search } = request.nextUrl;

  const target = legacy.get(normalize(pathname)) ?? legacy.get(normalize(pathname).toLowerCase());
  if (target) {
    const url = request.nextUrl.clone();
    const [targetPath, targetQuery] = target.split("?");
    url.pathname = targetPath;
    url.search = targetQuery ? `?${targetQuery}` : "";
    return NextResponse.redirect(url, 301);
  }

  const first = pathname.split("/")[1];
  if (isLocale(first)) return NextResponse.next();

  const saved = request.cookies.get(LOCALE_COOKIE)?.value;
  const locale = isLocale(saved) ? saved : defaultLocale;
  const url = request.nextUrl.clone();
  url.pathname = `/${locale}${pathname === "/" ? "" : pathname}`;
  url.search = search;
  return NextResponse.redirect(url, pathname === "/" ? 307 : 308);
}

export const config = {
  // Skip API routes (uploads must not pass through the proxy body buffer),
  // Next internals and any file with an extension (static assets, sitemap.xml, robots.txt).
  matcher: ["/((?!api|_next|.*\\..*).*)"],
};
